C2 = ("«La mochila de Elisa. Elisa encontró una mochila abandonada en la plaza. Dentro había un cuaderno con dibujos y un nombre: Martín. "
      "Aunque la tentaban los lápices de colores, pensó en cómo se sentiría Martín. Buscó en el colegio, preguntó en cada curso y, tres días después, lo encontró. "
      "Martín no dijo nada, solo sonrió; y Elisa sintió que había recibido un regalo.»")
L(OA16, 3,
  "Este cuaderno y un lápiz.",
  "Aprenderé a seleccionar los mejores ejemplos del texto para fundamentar mi opinión, citando con comillas o parafraseando.",
  ["Conozco las partes de un comentario.", "Sé qué es una opinión fundamentada."],
  ["Un ejemplo es un hecho del texto que respalda mi opinión. Para elegirlo reviso el texto y busco un pasaje que muestre claramente lo que digo. Si opino que «Elisa es empática», un buen ejemplo es cuando «pensó en cómo se sentiría Martín». El ejemplo debe ser pertinente (se relaciona con mi opinión), claro (se entiende por sí solo) y fiel al texto (no cambia lo que pasa).",
   "Puedo usar el ejemplo de dos formas. La cita textual copia las palabras exactas del texto, entre comillas: Elisa «buscó en el colegio, preguntó en cada curso». La paráfrasis cuenta lo mismo con mis palabras: buscó en todos los cursos hasta encontrar al dueño. En ambas indico de qué parte del texto proviene. No debo inventar hechos que el texto no menciona.",
   "También conviene elegir pocos ejemplos, pero buenos. Un ejemplo bien explicado vale más que cinco sueltos. Después del ejemplo explico cómo lo apoya: «Esto muestra que se preocupó por otra persona». Así el lector entiende por qué lo elegí y se convence con razones, no solo con la repetición de lo que pasa."],
  [("pertinente", "que se relaciona con lo que se quiere probar"), ("cita textual", "copia exacta de una frase, entre comillas"), ("paráfrasis", "contar con otras palabras lo que dice el texto"), ("fiel al texto", "que no cambia lo que dice el texto"), ("pasaje", "parte de un texto")],
  [("Elegir el ejemplo adecuado", f"Texto: {C2} Opinión: «Elisa es una persona honesta». ¿Qué ejemplo la apoya: «Aunque la tentaban los lápices, buscó al dueño» o «Encontró la mochila en la plaza»?",
    ["La honestidad se muestra al no quedarse con lo ajeno.", "El primero muestra una decisión honesta."], "«Aunque la tentaban los lápices, buscó al dueño»"),
   ("Citar y parafrasear", f"Texto: {C2} Escribe una cita textual y una paráfrasis del pasaje «Martín no dijo nada, solo sonrió».",
    ["La cita textual va entre comillas con las palabras exactas.", "La paráfrasis dice lo mismo con otras palabras."], "Cita: «Martín no dijo nada, solo sonrió». Paráfrasis: Martín agradeció con una sonrisa, sin palabras")],
  [("Elegir un ejemplo que no tiene relación con la opinión.", "No la apoya.", "Revisa que el ejemplo muestre lo que dices."),
   ("Inventar hechos que el texto no dice.", "Se pierde la fidelidad al texto.", "Usa solo lo que está escrito.")],
  ([E("¿Una cita textual lleva comillas? Responde sí o no.", "Sí", "Copia palabras exactas."),
    E("Una paráfrasis cuenta lo mismo con tus palabras. ¿Verdadero o falso?", "Verdadero", "Esa es su definición."),
    E("Un ejemplo pertinente, ¿se relaciona con mi opinión? Responde sí o no.", "Sí", "El ejemplo debe apoyar la opinión.")],
   [E(f"Texto: {C2} ¿Dónde encontró Elisa la mochila?", "En la plaza", "El texto lo dice."),
    E(f"Texto: {C2} ¿Cuántos días tardó Elisa en encontrar a Martín?", "Tres días", "El texto dice «tres días después»."),
    E(f"Texto: {C2} ¿Qué objeto con dibujos había dentro de la mochila?", "Un cuaderno", "El texto lo menciona.")],
   [E(f"Texto: {C2} Opinión: «Elisa es perseverante». ¿Qué ejemplo sirve: «Buscó en el colegio y preguntó en cada curso» o «Martín sonrió»?", "Buscó en el colegio y preguntó en cada curso", "Muestra esfuerzo sostenido."),
    E("Convierte en paráfrasis: «Aunque la tentaban los lápices de colores, pensó en cómo se sentiría Martín». Elige: a) Pensó en Martín y no se quedó con los lápices. b) Se quedó con los lápices. Escribe la letra.", "a", "Dice lo mismo con otras palabras y respeta el texto."),
    arith("Imagina que Elisa hubiera preguntado en 6 cursos por día durante 3 días. ¿En cuántos cursos habría preguntado en total?", "6*3", "Se multiplican los cursos diarios por los días.", " cursos")],
   [E(f"Texto: {C2} Un compañero dice que Elisa se quedó con los lápices. ¿Es fiel al texto? Responde sí o no.", "No", "El texto muestra que pensó en Martín y lo buscó durante tres días para devolverle la mochila."),
    E("Un comentario dice «Elisa fue valiente» y da como ejemplo «Encontró una mochila». ¿El ejemplo es pertinente? Responde sí o no.", "No", "Encontrar una mochila no demuestra valentía.")],
   [E(f"Texto: {C2} Opinión: «La honestidad trae alegría». Elige el ejemplo más fuerte: a) «Elisa sintió que había recibido un regalo». b) «Elisa estaba en una plaza». Escribe la letra.", "a", "Muestra la alegría que le dio devolver la mochila."),
    E("Un estudiante cita mal: escribe «buscó por todas partes del mundo» entre comillas, pero el texto dice «buscó en el colegio». ¿La cita es textual? Responde sí o no.", "No", "Cambió las palabras exactas del texto.")]),
  [E("Quieres defender que Martín fue agradecido. En el cuento, ¿qué ejemplo usas: «Martín no dijo nada, solo sonrió» o «Elisa encontró una mochila»?", "Martín no dijo nada, solo sonrió", "Muestra su gratitud.")],
  [E("¿Qué es una paráfrasis?", "Contar con mis palabras lo que dice el texto", "No usa comillas."),
   E("¿Cómo señalo una cita textual?", "Con comillas", "Indica palabras exactas."),
   E("¿Qué debo hacer después de poner un ejemplo?", "Explicar cómo apoya mi opinión", "Así el lector entiende la conexión.")],
  (f"Lee este cuento: {C2} Elige una opinión (por ejemplo: «Elisa es empática», «Elisa es perseverante» o «La honestidad se premia») y escribe dos ejemplos del texto que la apoyen: uno como cita textual y otro como paráfrasis. Después explica en una oración cómo apoyan tu opinión.",
   "Opinión: Elisa es perseverante. Cita: «Buscó en el colegio, preguntó en cada curso». Paráfrasis: no se rindió hasta encontrar a Martín tres días después. Ambos muestran que siguió buscando aunque costara tiempo.",
   ["opinión clara", "una cita textual y una paráfrasis", "ejemplos fieles al texto", "explicación final"], ["la opinión, los dos ejemplos y la explicación"],
   ["cambiar las palabras de una cita", "ejemplos que no apoyan"], "Pide a alguien que compruebe tus ejemplos en el texto."),
  "Elige una frase de un libro que te guste y cópiala entre comillas con su página.",
  "Parafrasea una oración de un texto que hayas leído hoy.")

